"""Export a trained adapter: PEFT dir, merged model, or GGUF + Ollama Modelfile.

Also provides the ``register_for_chatbot`` tool that writes an Ollama Modelfile
and (optionally) registers the adapter with a local Ollama daemon, plus a
``chat_with_adapter`` helper that talks to a local endpoint.
"""

from __future__ import annotations

import json
import os
import shutil
import subprocess
from pathlib import Path

from .models import JobRecord
from .store import Workspace

EXPORT_FORMATS = ("peft", "merged", "gguf")

MODELFILE_TMPL = """\
# Generated by dk-lora for model: {model_name}
FROM {gguf_path}
TEMPLATE \"\"\"{template}\"\"\"
PARAMETER temperature 0.7
PARAMETER top_p 0.9
PARAMETER stop "### Response:"
PARAMETER stop "</s>"
"""


def _adapter_dir(job: JobRecord) -> Path:
    return Path(job.output_dir) / "adapter"


def _require_done(job: JobRecord, job_id: str) -> Path:
    if job is None:
        raise ValueError(f"job not found: {job_id}")
    if job.status != "done":
        raise ValueError(f"job {job_id} is '{job.status}', not 'done' — "
                         "training must finish before export")
    adapter = _adapter_dir(job)
    if not adapter.exists():
        raise ValueError(f"adapter directory missing at {adapter} — the "
                         "training job may have produced nothing")
    return adapter


def export_adapter(ws: Workspace, job_id: str,
                   format: str = "peft",
                   merge: bool = False) -> dict:
    """Export a finished job's adapter in peft / merged / gguf form.

    Returns a dict of produced paths plus, for gguf, a ready-to-use Ollama
    Modelfile (``ollama create <name> -f <Modelfile>``).
    """
    if format not in EXPORT_FORMATS:
        raise ValueError(f"unknown format '{format}' (expected one of "
                         f"{EXPORT_FORMATS})")
    job = ws.get_job(job_id)
    adapter = _require_done(job, job_id)
    out_root = Path(job.output_dir)

    if format == "peft":
        return _export_peft(adapter, out_root, job)

    if format == "merged":
        return _export_merged(adapter, out_root, job, do_merge=merge)

    # gguf
    return _export_gguf(adapter, out_root, job)


def _export_peft(adapter: Path, out_root: Path, job: JobRecord) -> dict:
    readme = _adapter_readme(adapter, job, mode="peft")
    (out_root / "README.md").write_text(readme, encoding="utf-8")
    files = sorted(p.name for p in adapter.iterdir())
    return {
        "format": "peft", "adapter_path": str(adapter),
        "files": files, "readme": str(out_root / "README.md"),
        "load_instructions": (
            "from peft import PeftModel\\n"
            f"model = PeftModel.from_pretrained(base_model, '{adapter}')\\n"
            "# base_model is: " + job.config.get("base_model", ""),
        ),
    }


def _export_merged(adapter: Path, out_root: Path, job: JobRecord,
                   do_merge: bool) -> dict:
    script = out_root / "merge_unsloth.py"
    script.write_text(_merge_script(adapter, out_root, job), encoding="utf-8")
    merged_dir = out_root / "merged"
    if do_merge:
        # Best-effort actual merge with Unsloth if available.
        try:
            proc = subprocess.run([shutil.which("python") or "python",
                                   str(script)], capture_output=True,
                                  text=True, timeout=1800)
            if proc.returncode == 0:
                merged_dir.mkdir(parents=True, exist_ok=True)
            else:
                merged_dir.mkdir(parents=True, exist_ok=True)
                (out_root / "merged" / "merge_error.log").write_text(
                    proc.stderr, encoding="utf-8")
        except Exception as e:  # noqa: BLE001
            (out_root / "merged" / "merge_error.log").write_text(str(e),
                                                                 encoding="utf-8")
    (out_root / "README.md").write_text(
        _adapter_readme(adapter, job, mode="merged"), encoding="utf-8")
    return {"format": "merged", "merge_script": str(script),
            "merged_path": str(merged_dir),
            "note": "Run merge_unsloth.py on a GPU to produce the merged weights."}


def _merge_script(adapter: Path, out_root: Path, job: JobRecord) -> str:
    return f'''\
"""Merge the {adapter.name} LoRA adapter into the base weights with Unsloth."""
from unsloth import FastLanguageModel
base = {json.dumps(job.config.get("base_model", ""))}
model, tokenizer = FastLanguageModel.from_pretrained(model_name=base, max_seq_length=2048)
model = FastLanguageModel.from_pretrained(model, load_in_4bit=False, device_map="auto")
model = model.load_adapter({json.dumps(str(adapter))})
model = model.merge_and_unload()
model.save_pretrained({json.dumps(str(out_root / "merged"))})
tokenizer.save_pretrained({json.dumps(str(out_root / "merged"))})
print("MERGED_OK")
'''


def _export_gguf(adapter: Path, out_root: Path, job: JobRecord) -> dict:
    gguf_dir = out_root / "gguf"
    gguf_dir.mkdir(parents=True, exist_ok=True)
    convert = gguf_dir / "convert_to_gguf.sh"
    model_name = job.config.get("base_model", "").split("/")[-1] or "model"
    convert.write_text(_gguf_convert_script(adapter, gguf_dir, model_name),
                       encoding="utf-8")
    modelfile = gguf_dir / "Modelfile"
    modelfile.write_text(MODELFILE_TMPL.format(
        model_name=model_name, gguf_path=str(gguf_dir / "model.gguf"),
        template="### Instruction: {{.Prompt}}\\n\\n### Response:",
    ), encoding="utf-8")
    (out_root / "README.md").write_text(
        _adapter_readme(adapter, job, mode="gguf"), encoding="utf-8")
    return {
        "format": "gguf", "gguf_dir": str(gguf_dir),
        "convert_script": str(convert),
        "modelfile": str(modelfile),
        "ollama_command": f"ollama create {model_name.lower().replace('.', '-')} -f {modelfile}",
        "note": "Run convert_to_gguf.sh (needs llama.cpp) then the ollama create command.",
    }


def _gguf_convert_script(adapter: Path, gguf_dir: Path, model_name: str) -> str:
    return f'''\
#!/usr/bin/env bash
# Convert the merged HuggingFace model to GGUF using llama.cpp (adjust paths).
# First merge: python {adapter.parent / "merge_unsloth.py"}
LLAMA_CPP=/path/to/llama.cpp
python "$LLAMA_CPP/convert_hf_to_gguf.py" {adapter.parent / "merged"} \\
  --outfile {gguf_dir / "model.gguf"} --outtype f16
# Then: ollama create {model_name.lower().replace(".", "-")} -f {gguf_dir / "Modelfile"}
'''


def _adapter_readme(adapter: Path, job: JobRecord, mode: str) -> str:
    base = job.config.get("base_model", "")
    return f"""\
# dk-lora adapter ({job.id})

Trained with the **dk-lora** MCP server.

- Base model: `{base}`
- Adapter: `{adapter}`
- Backend: `{job.config.get('backend', 'unsloth')}`
- Output dir: `{job.output_dir}`

## Load with PEFT (transformers)

```python
from peft import PeftModel
from transformers import AutoModelForCausalLM, AutoTokenizer

base = "{base}"
model = AutoModelForCausalLM.from_pretrained(base, device_map="auto")
tokenizer = AutoTokenizer.from_pretrained(base)
model = PeftModel.from_pretrained(model, "{adapter}")
```

## Load with Unsloth

```python
from unsloth import FastLanguageModel
model, tokenizer = FastLanguageModel.from_pretrained("{base}", max_seq_length=2048)
model = model.load_adapter("{adapter}")
```

## {mode.upper()} artifacts
- `{adapter}` — PEFT adapter weights
{f"- `{adapter.parent / 'merged'}` — merged base+adapter weights" if mode == "merged" else ""}
{f"- `{adapter.parent / 'gguf' / 'Modelfile'}` — Ollama Modelfile" if mode == "gguf" else ""}
"""


def register_for_chatbot(ws: Workspace, job_id: str, name: str = "dk-lora",
                         modelfile_path: str = "", ollama: bool = True) -> dict:
    """Write an Ollama Modelfile for a finished job and register it (optional).

    If ``ollama`` is True, runs ``ollama create`` against the local daemon.
    """
    job = ws.get_job(job_id)
    adapter = _require_done(job, job_id)
    if modelfile_path:
        modelfile = Path(modelfile_path).expanduser().resolve()
    else:
        modelfile = Path(job.output_dir) / "gguf" / "Modelfile"
        if not modelfile.exists():
            modelfile = Path(job.output_dir) / "Modelfile"
            modelfile.write_text(MODELFILE_TMPL.format(
                model_name=name, gguf_path=str(adapter),
                template="### Instruction: {{.Prompt}}\\n\\n### Response:",
            ), encoding="utf-8")
    result = {
        "name": name, "modelfile": str(modelfile),
        "adapter_path": str(adapter),
    }
    if ollama:
        if shutil.which("ollama") is None:
            result["ollama_registered"] = False
            result["error"] = ("ollama binary not found on PATH — run "
                               f"`ollama create {name} -f {modelfile}` manually")
            return result
        try:
            proc = subprocess.run(["ollama", "create", name, "-f", str(modelfile)],
                                  capture_output=True, text=True, timeout=600)
            if proc.returncode == 0:
                result["ollama_registered"] = True
                result["ollama_model"] = name
            else:
                result["ollama_registered"] = False
                result["error"] = proc.stderr.strip()
        except Exception as e:  # noqa: BLE001
            result["ollama_registered"] = False
            result["error"] = f"{type(e).__name__}: {e}"
    return result


def chat_with_adapter(message: str, adapter_path: str,
                      system_prompt: str | None = None,
                      endpoint: str = "",
                      model_name: str = "dk-lora") -> dict:
    """Ask a local Ollama/llama.cpp endpoint to answer with the adapter.

    The adapter must already be registered (see register_for_chatbot). Endpoint
    defaults to ``OLLAMA_HOST`` (http://127.0.0.1:11434).
    """
    if not message or not message.strip():
        raise ValueError("message is required")
    if not adapter_path.strip():
        raise ValueError("adapter_path is required")
    host = endpoint or os.environ.get("OLLAMA_HOST", "http://127.0.0.1:11434")
    payload = json.dumps({
        "model": model_name,
        "prompt": (system_prompt + "\n\n" if system_prompt else "") + message,
        "stream": False,
        "options": {"temperature": 0.3},
    }).encode()
    import urllib.request
    req = urllib.request.Request(f"{host}/api/generate", data=payload,
                                 headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=300) as resp:
            data = json.loads(resp.read().decode())
        return {"ok": True, "model": model_name, "response": data.get("response", "")}
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "error": f"{type(e).__name__}: {e}",
                "recovery": f"Start Ollama (ollama serve) and register the adapter "
                            f"first (ollama create {model_name} -f <Modelfile>). "
                            f"Check OLLAMA_HOST={host}"}
